use std::{env, fs, path::PathBuf};

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let manifest_dir = PathBuf::from(env::var("CARGO_MANIFEST_DIR")?);
    println!(
        "cargo::rerun-if-changed={}",
        manifest_dir.join("rom_tests.yaml").display()
    );
    let out_dir = PathBuf::from(env::var("OUT_DIR")?);
    fs::write(
        out_dir.join("generated_rom_manifest_tests.rs"),
        "// @generated by gba/rom_test/build.rs - do not edit manually.\n\
         #[test]\n\
         fn available_manifest_roms() { crate::run_available_manifest_roms(); }\n",
    )?;
    Ok(())
}
